134→func (d *Droid) RunPrompt(ctx context.Context, dir string, prompt string, opts ...Option) (Output, error) {
135→	cfg := &runConfig{Model: defaultDroidModel}
136→	for _, o := range opts {
137→		o(cfg)
138→	}
139→
140→	model := cfg.Model
141→	if model == "" {
142→		model = defaultDroidModel
143→	}
144→
145→	args := []string{"exec", "--skip-permissions-unsafe", "--model", model, prompt}
146→	displayArgs := []string{"exec", "--skip-permissions-unsafe", "--model", model, fmt.Sprintf("%q", prompt)}
147→
148→	cmd := exec.CommandContext(ctx, d.Binary(), args...)
149→	cmd.Dir = dir
150→	cmd.Stdin = nil
151→	cmd.Env = filterEnv(os.Environ(), "ENTIRE_TEST_TTY", "CI", "GITHUB_ACTIONS")
152→	cmd.SysProcAttr = &syscall.SysProcAttr{Setpgid: true}
153→	cmd.Cancel = func() error {
154→		return syscall.Kill(-cmd.Process.Pid, syscall.SIGKILL)
155→	}
156→	cmd.WaitDelay = 5 * time.Second
157→
158→	var stdout, stderr strings.Builder
159→	cmd.Stdout = &stdout
160→	cmd.Stderr = &stderr
161→
162→	err := cmd.Run()
163→	exitCode := 0
164→	if err != nil {
165→		exitErr := &exec.ExitError{}
166→		if errors.As(err, &exitErr) {
167→			exitCode = exitErr.ExitCode()
168→		} else {
169→			exitCode = -1
170→		}
171→	}
172→
173→	return Output{
174→		Command:  d.Binary() + " " + strings.Join(displayArgs, " "),
175→		Stdout:   stdout.String(),
176→		Stderr:   stderr.String(),
177→		ExitCode: exitCode,
178→	}, err
179→}
