 90→const (
 91→	settleTime   = 2 * time.Second
 92→	pollInterval = 500 * time.Millisecond
 93→)
 94→
 95→// stableContent returns the content with the last few lines stripped,
 96→// so that TUI status bar updates don't prevent the settle timer.
 97→func stableContent(content string) string {
 98→	lines := strings.Split(content, "\n")
 99→	if len(lines) > 3 {
100→		lines = lines[:len(lines)-3]
101→	}
102→	return strings.Join(lines, "\n")
103→}
104→
105→func (s *TmuxSession) WaitFor(pattern string, timeout time.Duration) (string, error) {
106→	re, err := regexp.Compile(pattern)
107→	if err != nil {
108→		return "", fmt.Errorf("invalid pattern: %w", err)
109→	}
110→
111→	deadline := time.Now().Add(timeout)
112→	var matchedAt time.Time
113→	var lastStable string
114→	contentChanged := s.stableAtSend == "" // skip change requirement for initial waits
115→
116→	for time.Now().Before(deadline) {
117→		content := s.Capture()
118→		stable := stableContent(content)
119→
120→		// Bail early if the process has exited and the pattern doesn't match.
121→		// remain-on-exit keeps the pane alive, so without this check we'd
122→		// poll a dead pane for the full timeout duration.
123→		if !re.MatchString(content) {
124→			if s.IsPaneDead() {
125→				return content, fmt.Errorf("process exited while waiting for %q\n--- pane content ---\n%s\n--- end pane content ---", pattern, content)
126→			}
127→			// Pattern lost — reset
128→			matchedAt = time.Time{}
129→			lastStable = ""
130→			time.Sleep(pollInterval)
131→			continue
132→		}
133→
134→		// Detect content change since Send was called
135→		if !contentChanged && stable != s.stableAtSend {
136→			contentChanged = true
137→		}
138→
139→		if stable != lastStable {
140→			// Pattern matches but content is still changing — reset settle timer
141→			matchedAt = time.Now()
142→			lastStable = stable
143→			time.Sleep(pollInterval)
144→			continue
145→		}
146→
147→		// Pattern matches and content hasn't changed since matchedAt.
148→		// Only settle if content changed at least once after Send
149→		// (prevents false settle on echoed input before agent starts).
150→		if contentChanged && time.Since(matchedAt) >= settleTime {
151→			return content, nil
152→		}
153→
154→		time.Sleep(pollInterval)
155→	}
156→	content := s.Capture()
157→	return content, fmt.Errorf("timed out waiting for %q after %s\n--- pane content ---\n%s\n--- end pane content ---", pattern, timeout, content)
158→}
