160→// IsPaneDead returns true if the process inside the tmux pane has exited.
161→// This relies on the remain-on-exit option being set (which NewTmuxSession does).
162→func (s *TmuxSession) IsPaneDead() bool {
163→	cmd := exec.Command("tmux", "display-message", "-t", s.name, "-p", "#{pane_dead}")
164→	out, err := cmd.Output()
165→	if err != nil {
166→		return false
167→	}
168→	return strings.TrimSpace(string(out)) == "1"
169→}
170→
171→func (s *TmuxSession) Capture() string {
172→	cmd := exec.Command("tmux", "capture-pane", "-t", s.name, "-p")
173→	out, _ := cmd.Output()
174→	return strings.TrimRight(string(out), "\n")
175→}
176→
177→func (s *TmuxSession) Close() error {
178→	for _, fn := range s.cleanups {
179→		fn()
180→	}
181→	cmd := exec.Command("tmux", "kill-session", "-t", s.name)
182→	out, err := cmd.CombinedOutput()
183→	if err != nil {
184→		return fmt.Errorf("tmux kill-session: %w\n%s", err, out)
185→	}
186→	return nil
187→}
